<?php

namespace App\Http\Controllers;

use Illuminate\Http\RedirectResponse;
use Illuminate\Http\Request;
use Illuminate\View\View;

/**
 * The in-app notification inbox, for clients, staff and administrators alike.
 *
 * One screen for every role rather than three near-identical ones: the rows are
 * generated by the same code for all of them, and what differs is only where a
 * row links to. A client follows it to their appointment; staff and
 * administrators have no appointment of their own to follow, so those rows are
 * informational.
 *
 * Nothing here is role-guarded beyond being signed in: a notification belongs
 * to the account that received it, and the query is always scoped to the
 * signed-in user's own rows.
 */
class NotificationInboxController extends Controller
{
    public function index(Request $request): View
    {
        $user = $request->user();

        $notifications = $user->notifications()
            // Newest first, and by id rather than created_at so two messages
            // written in the same second keep a stable order.
            ->latest()
            ->paginate(25)
            ->withQueryString();

        return view('notifications.index', [
            'notifications' => $notifications,
            'unreadCount' => $user->unreadNotifications()->count(),
            // Only a client has appointments to follow a notification into.
            'canFollowAppointments' => $user->isClient(),
        ]);
    }

    /**
     * Mark one as read and go wherever it points.
     *
     * Two destinations, and the order matters. An ops message carries its own
     * in-app route, which is what the author chose and is the useful place to
     * land. A client message is followed back to the appointment, but only
     * through the signed-in user's own appointments relation - an id in the
     * payload is not authorisation to open somebody else's record, and resolving
     * it that way is what makes this check meaningful rather than decorative.
     */
    public function read(Request $request, string $id): RedirectResponse
    {
        $notification = $request->user()->notifications()->findOrFail($id);

        $notification->markAsRead();

        $data = $notification->data;

        $opsUrl = $data['url'] ?? null;

        // Only followed for a URL this app issued. The payload is generated
        // server-side, but validating the shape means a malformed or
        // hand-inserted row cannot turn "open this message" into an open
        // redirect off-site.
        if (is_string($opsUrl) && str_starts_with($opsUrl, url('/')) && $request->user()->isBackOffice()) {
            return redirect()->to($opsUrl);
        }

        $appointmentId = $data['appointment_id'] ?? null;

        if ($appointmentId && $request->user()->isClient()) {
            $appointment = $request->user()->appointments()->find($appointmentId);

            if ($appointment) {
                return redirect()->route('client.appointments.show', $appointment);
            }
        }

        return redirect()->route('notifications.index');
    }

    public function readAll(Request $request): RedirectResponse
    {
        $request->user()->unreadNotifications->markAsRead();

        return redirect()->route('notifications.index')
            ->with('success', 'All messages marked as read.');
    }

    /**
     * Remove a message from this account's inbox.
     *
     * Only ever the signed-in user's own row: the route takes the notification id
     * but the delete is scoped to the owner, so an id from somebody else's inbox
     * simply is not found - a 404, not a delete.
     */
    public function destroy(Request $request, string $id): RedirectResponse
    {
        $request->user()->notifications()->findOrFail($id)->delete();

        return back()->with('success', 'Message removed.');
    }
}
